/* ChkptResultHistMapper.selectExistsAnswer */
SELECT COUNT(1)
FROM TB_CHKPT_INSPECT_ANSWER
WHERE CMPNY_CD        = #{cmpnyCd}
  AND SITE_CD         = #{siteCd}
  AND CHKPT_CD        = #{chkptCd}
  AND INSPECT_ITEM_CD = #{inspectItemCd}
  AND WORK_DATE       = #{workDate}

/* ChkptResultHistMapper.selectExistsDefectAction */
SELECT COUNT(1)
FROM TB_CHKPT_DEFECT_ACTION
WHERE CMPNY_CD        = #{cmpnyCd}
  AND SITE_CD         = #{siteCd}
  AND CHKPT_CD        = #{chkptCd}
  AND INSPECT_ITEM_CD = #{inspectItemCd}
  AND WORK_DATE       = #{workDate}
